package main
import ("fmt";"os";"gopkg.in/yaml.v3")
func main(){
 for _,f:=range os.Args[1:]{
  b,_:=os.ReadFile(f)
  var m map[string]interface{}
  if err:=yaml.Unmarshal(b,&m);err!=nil{fmt.Println("  FAIL",f,err);os.Exit(1)}
  j:=m["jobs"].(map[string]interface{})
  ks:=[]string{}
  for k:=range j{ks=append(ks,k)}
  fmt.Println("  ok ",f,"jobs:",ks)
 }
}
EOF
