	args := []string{"rev-parse", "HEAD"}
	if explicit {
		args = []string{"rev-parse", "--verify", branch + "^{commit}"}
	}
	commit, err := gitScalar(ctx, opts.Runner, repoDir, args...)
	if err != nil {
		return "", false
	}
	commit = strings.TrimSpace(commit)
	return commit, commit != ""
}

