func TestMCPToolDescriptionsOnlyNameToolsThatExist(t *testing.T) {
	repoDir := seedFixtureRepo(t)
	opts := rememberTestOptions(t, repoDir)

	input := frameMCP(`{"jsonrpc":"2.0","id":1,"method":"tools/list","params":{}}`)
