13	// Facts as plain files.
14	//
15	// A brain's durable facts live in an internal store, reachable through `recall`
16	// and the MCP tools and nowhere else. That is fine until you want to do the
17	// obvious thing — grep them, read one in an editor, diff two branches, paste a
18	// decision into a review — and discover that the only way in is a program.
19	//
20	// This writes the same facts out as one Markdown file per fact, laid out by
21	// taxonomy path, so ordinary tools work on them:
22	//
23	//	constraints/retry/policy/fact-57e03e4a.md
24	//	architecture/api/ports/fact-1b3c8686.md
25	//
26	// The export is a projection, not a second source of truth. It is written fresh
27	// each time, the store remains authoritative, and nothing here reads the files
28	// back in. That is a deliberate limit: a format people edit and a store a
29	// program owns will diverge, and the honest version of this feature is the one
30	// that says which direction is canonical rather than pretending to sync.
31	
32	// factFileName is the per-fact filename. The id is already content-addressed
33	// and unique; the short form keeps paths readable while staying collision-free
34	// within a taxonomy directory.
35	func factFileName(id string) string {
36		trimmed := strings.TrimPrefix(id, "fact:")
37		if len(trimmed) > 12 {
38			trimmed = trimmed[:12]
39		}
40		if trimmed == "" {
41			trimmed = "unidentified"
42		}
43		return "fact-" + trimmed + ".md"
44	}
45	
46	// factFileDir maps a taxonomy path to a directory. A fact with no path lands in
47	// "unfiled" rather than the export root, so the root stays a list of categories
48	// and an unfiled fact is visibly unfiled instead of quietly mixed in.
49	func factFileDir(paths []string) string {
50		if len(paths) == 0 || strings.TrimSpace(paths[0]) == "" {
51			return "unfiled"
52		}
53		segments := strings.Split(strings.TrimSpace(paths[0]), ".")
54		safe := make([]string, 0, len(segments))
55		for _, segment := range segments {
56			segment = sanitizeFactPathSegment(segment)
57			if segment != "" {
58				safe = append(safe, segment)
59			}
60		}
61		if len(safe) == 0 {
62			return "unfiled"
63		}
64		return filepath.Join(safe...)
65	}
66	
67	// sanitizeFactPathSegment keeps a taxonomy segment to characters that are safe
68	// in a path on every platform we ship to. A taxonomy is author-controlled, but
69	// it is still data, and data must not be able to write outside the export
70	// directory — so separators and traversal are stripped rather than escaped.
71	func sanitizeFactPathSegment(segment string) string {
72		segment = strings.TrimSpace(segment)
73		if segment == "." || segment == ".." {
74			return ""
75		}
76		var b strings.Builder
77		for _, r := range segment {
78			switch {
79			case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9':
80				b.WriteRune(r)
81			case r == '-', r == '_':
82				b.WriteRune(r)
83			default:
84				b.WriteRune('-')
85			}
86		}
87		return strings.Trim(b.String(), "-")
88	}
89	
90	// renderFactFile is the file body: YAML-ish front matter a human can read and a
91	// script can parse, then the fact itself as prose. The fact text is last and
92	// unindented so `grep -r` output reads as the sentence, not as metadata.
93	func renderFactFile(fact factRecord) string {
94		var b strings.Builder
95		b.WriteString("---\n")
96		fmt.Fprintf(&b, "id: %s\n", fact.ID)
97		if fact.Kind != "" {
98			fmt.Fprintf(&b, "kind: %s\n", fact.Kind)
99		}
100		if len(fact.Paths) > 0 {
101			fmt.Fprintf(&b, "paths: %s\n", strings.Join(fact.Paths, ", "))
102		}
103		if fact.Branch != "" {
104			fmt.Fprintf(&b, "branch: %s\n", fact.Branch)
105		}
106		if fact.Status != "" {
107			fmt.Fprintf(&b, "status: %s\n", fact.Status)
108		}
109		if fact.Origin != "" {
110			fmt.Fprintf(&b, "origin: %s\n", fact.Origin)
111		}
112		if len(fact.Locus) > 0 {
113			fmt.Fprintf(&b, "locus: %s\n", strings.Join(fact.Locus, ", "))
114		}
115		if !fact.CreatedAt.IsZero() {
116			fmt.Fprintf(&b, "created_at: %s\n", fact.CreatedAt.UTC().Format("2006-01-02T15:04:05Z"))
117		}
118		if !fact.UpdatedAt.IsZero() {
119			fmt.Fprintf(&b, "updated_at: %s\n", fact.UpdatedAt.UTC().Format("2006-01-02T15:04:05Z"))
120		}
121		// Provenance is what separates a fact from an assertion, so it belongs in
122		// the file rather than only in the store.
123		for _, anchor := range fact.Provenance {
124			switch {
125			case anchor.Commit != "":
126				fmt.Fprintf(&b, "anchor: commit %s\n", anchor.Commit)
127			case anchor.SessionID != "":
128				fmt.Fprintf(&b, "anchor: session %s\n", anchor.SessionID)
129			case anchor.CheckpointID != "":
130				fmt.Fprintf(&b, "anchor: checkpoint %s\n", anchor.CheckpointID)
131			}
132		}
133		b.WriteString("---\n\n")
134		b.WriteString(strings.TrimSpace(fact.Text))
135		b.WriteString("\n")
136		return b.String()
137	}
