145	// writeFactFiles materialises facts under dir. Returns the relative paths
146	// written, sorted, so the caller can print or diff them deterministically.
147	func writeFactFiles(dir string, facts []factRecord) (factFilesResult, error) {
148		result := factFilesResult{Dir: dir}
149		if err := os.MkdirAll(dir, 0o755); err != nil {
150			return result, fmt.Errorf("create export directory: %w", err)
151		}
152		for _, fact := range facts {
