// properties that make it worth having: ordinary tools work on it, a taxonomy
// cannot write outside it, and it never pretends to be a second source of truth.

func factFixture(id, text string, paths []string) factRecord {
	return factRecord{
		ID:        id,
		Paths:     paths,
		Kind:      "invariant",
		Text:      text,
		Branch:    "main",
		Origin:    "authored",
		Status:    "active",
		CreatedAt: time.Date(2026, 9, 21, 12, 0, 0, 0, time.UTC),
		UpdatedAt: time.Date(2026, 9, 21, 12, 0, 0, 0, time.UTC),
	}
}

func TestFactFilesAreGreppableAndReadable(t *testing.T) {
	dir := t.TempDir()
	facts := []factRecord{
