52	func restLimit(r *http.Request, fallback, max int) (int, error) {
53		raw := strings.TrimSpace(r.URL.Query().Get("limit"))
54		if raw == "" {
55			return fallback, nil
56		}
57		value, err := strconv.Atoi(raw)
58		if err != nil {
59			return 0, fmt.Errorf("limit must be an integer")
60		}
61		if value < 1 {
62			return 0, fmt.Errorf("limit must be at least 1")
63		}
64		if value > max {
65			return 0, fmt.Errorf("limit must be at most %d", max)
66		}
67		return value, nil
68	}
69	
70	const (
71		restDefaultLimit = 20
72		restMaxLimit     = 200
73	)
74	
75	// registerRESTRoutes adds the resource endpoints to an existing mux. The caller
76	// has already applied authentication, so nothing here re-implements it — one
77	// auth path for both surfaces is the point of sharing a listener.
78	func registerRESTRoutes(mux *http.ServeMux, opts Options) {
79		mux.HandleFunc(restAPIPrefix, func(w http.ResponseWriter, r *http.Request) {
80			resource := strings.Trim(strings.TrimPrefix(r.URL.Path, restAPIPrefix), "/")
81			switch {
82			case resource == "status" && r.Method == http.MethodGet:
83				restStatus(w, r, opts)
84			case resource == "facts" && r.Method == http.MethodGet:
85				restFacts(w, r, opts)
86			case resource == "search" && r.Method == http.MethodGet:
87				restSearch(w, r, opts)
88			case resource == "":
89				// A bare /v1/ lists what exists. An API you can discover from the
90				// root is one fewer document to keep in sync.
91				writeRESTJSON(w, map[string]any{
92					"endpoints": []map[string]string{
93						{"method": "GET", "path": "/v1/status", "description": "brain freshness and source counts"},
94						{"method": "GET", "path": "/v1/facts", "description": "durable facts; ?limit= and ?branch="},
95						{"method": "GET", "path": "/v1/search", "description": "hybrid retrieval; ?q= required, ?limit=, ?source="},
96						{"method": "POST", "path": "/", "description": "MCP JSON-RPC (the same tools the CLI exposes)"},
97					},
98					"auth": "Bearer token, the same one the MCP endpoint uses",
99				})
100			default:
101				writeRESTError(w, http.StatusNotFound,
102					fmt.Sprintf("no endpoint %s %s", r.Method, r.URL.Path),
103					"GET /v1/ lists the endpoints that exist")
104			}
105		})
106	}
107	
108	func restResolveTarget(r *http.Request, opts Options) (brainDir, branch string, err error) {
109		requested := strings.TrimSpace(r.URL.Query().Get("branch"))
110		_, brainDir, branch, err = resolveFactsTarget(r.Context(), opts, agentSurfaceTarget(opts, nil), requested)
111		return brainDir, branch, err
112	}
113	
114	func restStatus(w http.ResponseWriter, r *http.Request, opts Options) {
115		brainDir, branch, err := restResolveTarget(r, opts)
116		if err != nil {
117			writeRESTError(w, http.StatusBadRequest, err.Error(), "")
118			return
119		}
120		facts, err := loadFacts(brainDir, branch)
121		if err != nil {
122			writeRESTError(w, http.StatusInternalServerError, err.Error(), "")
123			return
124		}
125		active, superseded, retracted := 0, 0, 0
126		for _, fact := range facts {
127			switch fact.Status {
128			case "", factStatusActive:
129				active++
130			case "superseded":
131				superseded++
132			default:
133				retracted++
134			}
135		}
136		writeRESTJSON(w, map[string]any{
137			"branch": branch,
138			"facts": map[string]int{
139				"active": active, "superseded": superseded, "retracted": retracted, "total": len(facts),
140			},
141		})
142	}
143	
144	func restFacts(w http.ResponseWriter, r *http.Request, opts Options) {
145		limit, err := restLimit(r, restDefaultLimit, restMaxLimit)
146		if err != nil {
147			writeRESTError(w, http.StatusBadRequest, err.Error(), fmt.Sprintf("limit is 1..%d", restMaxLimit))
148			return
149		}
150		brainDir, branch, err := restResolveTarget(r, opts)
151		if err != nil {
152			writeRESTError(w, http.StatusBadRequest, err.Error(), "")
153			return
154		}
155		facts, err := loadFacts(brainDir, branch)
156		if err != nil {
157			writeRESTError(w, http.StatusInternalServerError, err.Error(), "")
158			return
159		}
160		// Retracted and superseded facts are excluded unless asked for. An API that
161		// returned them by default would hand a dashboard things the brain no
162		// longer believes.
163		includeAll := strings.EqualFold(strings.TrimSpace(r.URL.Query().Get("all")), "true")
164		out := make([]map[string]any, 0, limit)
165		for _, fact := range facts {
166			if !includeAll && fact.Status != "" && fact.Status != factStatusActive {
167				continue
168			}
169			if len(out) == limit {
170				break
171			}
172			out = append(out, map[string]any{
173				"id": fact.ID, "text": fact.Text, "kind": fact.Kind, "paths": fact.Paths,
174				"status": fact.Status, "origin": fact.Origin,
175				"created_at": fact.CreatedAt, "updated_at": fact.UpdatedAt,
176			})
177		}
178		writeRESTJSON(w, map[string]any{"branch": branch, "count": len(out), "limit": limit, "facts": out})
179	}
180	
181	func restSearch(w http.ResponseWriter, r *http.Request, opts Options) {
182		query := strings.TrimSpace(r.URL.Query().Get("q"))
183		if query == "" {
184			writeRESTError(w, http.StatusBadRequest, "q is required", "GET /v1/search?q=retry+policy")
185			return
186		}
187		limit, err := restLimit(r, restDefaultLimit, restMaxLimit)
188		if err != nil {
189			writeRESTError(w, http.StatusBadRequest, err.Error(), fmt.Sprintf("limit is 1..%d", restMaxLimit))
190			return
191		}
192		brainDir, branch, err := restResolveTarget(r, opts)
193		if err != nil {
194			writeRESTError(w, http.StatusBadRequest, err.Error(), "")
195			return
196		}
197		repoDir := opts.Env.RepoRoot
198		results, err := retrieveUnifiedWithOptions(repoDir, brainDir, branch, query, limit, modeHybrid,
199			retrievalOptions{Source: strings.TrimSpace(r.URL.Query().Get("source"))})
200		if err != nil {
201			writeRESTError(w, http.StatusInternalServerError, err.Error(), "")
202			return
203		}
204		writeRESTJSON(w, map[string]any{"branch": branch, "query": query, "count": len(results), "results": results})
205	}

