package cli

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// MCP is the right protocol for an agent and the wrong one for everything else.
// A dashboard, a CI check or a notebook had to speak JSON-RPC or parse CLI
// output. These tests cover the resource endpoints and, more importantly, that
// adding them did not open a hole in the listener they share.

func restServer(t *testing.T) (*httptest.Server, string) {
	t.Helper()
	opts := httpTestOptions(t)
	cfg := mcpHTTPConfig{Addr: "127.0.0.1:0", Token: "right-token", Loopback: true}
	server := httptest.NewServer(newMCPHTTPHandler(opts, cfg))
	t.Cleanup(server.Close)
	return server, "right-token"
}

func restGet(t *testing.T, server *httptest.Server, token, path string) (int, []byte) {
	t.Helper()
	req, _ := http.NewRequest(http.MethodGet, server.URL+path, nil)
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	resp, err := server.Client().Do(req)
	if err != nil {
		t.Fatalf("GET %s: %v", path, err)
	}
	defer resp.Body.Close()
	body := make([]byte, 0, 4096)
	buf := make([]byte, 4096)
	for {
		n, err := resp.Body.Read(buf)
		body = append(body, buf[:n]...)
		if err != nil {
			break
		}
	}
	return resp.StatusCode, body
}

func TestRESTEndpointsAreBehindTheSameAuthAsMCP(t *testing.T) {
	server, token := restServer(t)
	// The whole reason REST shares the MCP listener is that one auth path
	// cannot drift from another. If a new endpoint could be reached without a
	// token, sharing the listener bought nothing.
	for _, path := range []string{"/v1/", "/v1/status", "/v1/facts", "/v1/search?q=x", "/v1/nonexistent"} {
		if status, _ := restGet(t, server, "", path); status != http.StatusUnauthorized {
			t.Fatalf("%s without a token returned %d, want 401", path, status)
		}
		if status, _ := restGet(t, server, "wrong", path); status != http.StatusUnauthorized {
			t.Fatalf("%s with a wrong token returned %d, want 401", path, status)
		}
	}
	if status, _ := restGet(t, server, token, "/v1/"); status != http.StatusOK {
		t.Fatalf("the correct token was refused: %d", status)
	}
}

func TestRESTRootListsWhatExists(t *testing.T) {
	server, token := restServer(t)
	status, body := restGet(t, server, token, "/v1/")
	if status != http.StatusOK {
		t.Fatalf("status %d", status)
	}
	var payload struct {
		Endpoints []struct {
			Method string `json:"method"`
			Path   string `json:"path"`
		} `json:"endpoints"`
	}
	if err := json.Unmarshal(body, &payload); err != nil {
		t.Fatalf("decode: %v", err)
	}
	// An API discoverable from its root is one fewer document to keep in sync.
	seen := map[string]bool{}
	for _, e := range payload.Endpoints {
		seen[e.Path] = true
	}
	for _, want := range []string{"/v1/status", "/v1/facts", "/v1/search"} {
		if !seen[want] {
			t.Fatalf("the root does not list %s: %s", want, body)
		}
	}
}

func TestRESTRefusesUnboundedAndNonsenseLimits(t *testing.T) {
	server, token := restServer(t)
	// An unbounded limit on an endpoint that serialises records turns one
	// request into all of memory.
	for _, bad := range []string{"0", "-1", "abc", "100000"} {
		status, body := restGet(t, server, token, "/v1/facts?limit="+bad)
		if status != http.StatusBadRequest {
			t.Fatalf("limit=%s returned %d, want 400", bad, status)
		}
		if !strings.Contains(string(body), "limit") {
			t.Fatalf("limit=%s: the error should name the parameter: %s", bad, body)
		}
	}
	if status, _ := restGet(t, server, token, "/v1/facts?limit=5"); status != http.StatusOK {
		t.Fatalf("a valid limit was refused: %d", status)
	}
}

func TestRESTSearchRequiresAQueryAndSaysSo(t *testing.T) {
	server, token := restServer(t)
	status, body := restGet(t, server, token, "/v1/search")
	if status != http.StatusBadRequest {
		t.Fatalf("a search with no q returned %d, want 400", status)
	}
	// An error that shows the shape of a working call is worth more than one
	// that states a rule.
	if !strings.Contains(string(body), "/v1/search?q=") {
		t.Fatalf("the error should show a working example: %s", body)
	}
}

func TestRESTUnknownPathIsA404ThatPointsSomewhere(t *testing.T) {
	server, token := restServer(t)
	status, body := restGet(t, server, token, "/v1/nope")
	if status != http.StatusNotFound {
		t.Fatalf("unknown path returned %d, want 404", status)
	}
	if !strings.Contains(string(body), "/v1/") {
		t.Fatalf("a 404 should point at the discovery endpoint: %s", body)
	}
}

func TestRESTDidNotDisturbTheMCPEndpoint(t *testing.T) {
	server, token := restServer(t)
	// Mounting REST on this listener must not have shadowed the JSON-RPC POST
	// that was already there.
	req, _ := http.NewRequest(http.MethodPost, server.URL+"/",
		strings.NewReader(`{"jsonrpc":"2.0","id":1,"method":"tools/list","params":{}}`))
	req.Header.Set("Authorization", "Bearer "+token)
	resp, err := server.Client().Do(req)
	if err != nil {
		t.Fatalf("POST /: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("MCP POST returned %d after REST was added", resp.StatusCode)
	}
	var payload struct {
		Result struct {
			Tools []struct{ Name string } `json:"tools"`
		} `json:"result"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&payload); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(payload.Result.Tools) == 0 {
		t.Fatal("MCP tools/list came back empty after REST was mounted")
	}
}

/**
 * Entire Brain — TypeScript client.
 *
 * A brain runs on your machine and, until now, could only be reached by a
 * program willing to speak JSON-RPC or shell out to the CLI and parse its
 * output. This is the small amount of code that makes it an ordinary HTTP
 * service instead.
 *
 *   import { Brain } from "./entire-brain";
 *
 *   const brain = new Brain("http://127.0.0.1:7777", process.env.BRAIN_TOKEN!);
 *   for (const fact of await brain.facts()) console.log(fact.text);
 *   for (const hit of await brain.search("retry policy")) console.log(hit.source, hit.text);
 *
 * Start the server with:
 *
 *   entire brain mcp --http 7777
 *
 * It binds loopback and prints a bearer token. Nothing here works without one.
 *
 * No dependencies: global fetch only. A memory client that drags in a
 * dependency tree is a client people vendor rather than install.
 */

export interface Fact {
  id: string;
  text: string;
  kind?: string;
  paths?: string[];
  status?: string;
  origin?: string;
  created_at?: string;
  updated_at?: string;
}

export interface SearchHit {
  source: string;
  id: string;
  text: string;
  path?: string;
  heading?: string;
  score?: number;
}

export interface BrainStatus {
  branch: string;
  facts: { active: number; superseded: number; retracted: number; total: number };
}

/**
 * A request to a brain failed. Carries the status and the server's own message,
 * because "it broke" is not an error report. A 401 almost always means the
 * token is missing or stale, and saying so beats making the caller guess.
 */
export class BrainError extends Error {
  constructor(
    readonly status: number,
    readonly detail: string,
    readonly hint?: string,
  ) {
    let message = `brain request failed (${status}): ${detail}`;
    if (hint) message += `\n  ${hint}`;
    if (status === 401) {
      message += "\n  Check the bearer token printed by `entire brain mcp --http`.";
    }
    super(message);
    this.name = "BrainError";
  }
}

export class Brain {
  private readonly baseUrl: string;

  constructor(
    baseUrl: string,
    private readonly token: string,
    private readonly timeoutMs = 30_000,
  ) {
    if (!token) {
      // Failing in the constructor rather than at the first request: an empty
      // token is a configuration mistake, and a 401 three calls later is a
      // worse way to find out about it.
      throw new Error("a bearer token is required; `entire brain mcp --http` prints one");
    }
    this.baseUrl = baseUrl.replace(/\/+$/, "");
  }

  private async get<T>(path: string, params: Record<string, unknown> = {}): Promise<T> {
    const url = new URL(this.baseUrl + path);
    for (const [key, value] of Object.entries(params)) {
      if (value !== undefined && value !== null) url.searchParams.set(key, String(value));
    }
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), this.timeoutMs);
    let response: Response;
    try {
      response = await fetch(url, {
        headers: { Authorization: `Bearer ${this.token}` },
        signal: controller.signal,
      });
    } catch (cause) {
      throw new BrainError(0, `could not reach ${this.baseUrl}: ${String(cause)}`);
    } finally {
      clearTimeout(timer);
    }
    const body = await response.text();
    if (!response.ok) {
      try {
        const parsed = JSON.parse(body) as { error?: string; hint?: string };
        throw new BrainError(response.status, parsed.error ?? body, parsed.hint);
      } catch (error) {
        if (error instanceof BrainError) throw error;
        throw new BrainError(response.status, body.trim() || response.statusText);
      }
    }
    return JSON.parse(body) as T;
  }

  /** Fact counts for a branch: active, superseded, retracted, total. */
  status(branch?: string): Promise<BrainStatus> {
    return this.get<BrainStatus>("/v1/status", { branch });
  }

  /**
   * Durable facts. Superseded and retracted facts are excluded unless
   * includeAll is set: a caller rendering these should not be shown things the
   * brain no longer believes.
   */
  async facts(options: { limit?: number; branch?: string; includeAll?: boolean } = {}): Promise<Fact[]> {
    const payload = await this.get<{ facts: Fact[] }>("/v1/facts", {
      limit: options.limit ?? 20,
      branch: options.branch,
      all: options.includeAll ? "true" : undefined,
    });
    return payload.facts ?? [];
  }

  /**
   * Hybrid retrieval across facts, history and docs. `source` narrows the
   * corpus ("fact" | "history" | "doc"); omitting it searches the default set.
   */
  async search(
    query: string,
    options: { limit?: number; source?: string; branch?: string } = {},
  ): Promise<SearchHit[]> {
    if (!query.trim()) throw new Error("query must not be empty");
    const payload = await this.get<{ results: SearchHit[] }>("/v1/search", {
      q: query,
      limit: options.limit ?? 20,
      source: options.source,
      branch: options.branch,
    });
    return payload.results ?? [];
  }

  /** What this server exposes. Useful when a client is newer than a brain. */
  async endpoints(): Promise<Array<{ method: string; path: string; description: string }>> {
    const payload = await this.get<{ endpoints: Array<{ method: string; path: string; description: string }> }>("/v1/");
    return payload.endpoints ?? [];
  }
}

"""Entire Brain — Python client.

A brain runs on your machine and, until now, could only be reached by a program
willing to speak JSON-RPC or shell out to the CLI and parse its output. This is
the small amount of code that makes it an ordinary HTTP service instead.

    from entire_brain import Brain

    brain = Brain("http://127.0.0.1:7777", token="…")
    for fact in brain.facts():
        print(fact["text"])

    for hit in brain.search("retry policy"):
        print(hit["source"], hit["text"])

Start the server with:

    entire brain mcp --http 7777

It binds loopback and prints a bearer token. Nothing here works without one —
that is deliberate, and explained in the server's own documentation.

Standard library only. A memory client that drags in a dependency tree is a
client people vendor rather than install.
"""

from __future__ import annotations

import json
import urllib.error
import urllib.parse
import urllib.request
from typing import Any, Iterable

__all__ = ["Brain", "BrainError"]


class BrainError(RuntimeError):
    """A request to a brain failed.

    Carries the status code and the server's own message, because "it broke" is
    not an error report. A 401 here almost always means the token is missing or
    stale, and saying so beats making the caller guess.
    """

    def __init__(self, status: int, message: str, hint: str = "") -> None:
        self.status = status
        self.message = message
        self.hint = hint
        detail = f"brain request failed ({status}): {message}"
        if hint:
            detail += f"\n  {hint}"
        if status == 401:
            detail += "\n  Check the bearer token printed by `entire brain mcp --http`."
        super().__init__(detail)


class Brain:
    """A client for one brain over HTTP."""

    def __init__(self, base_url: str, token: str, timeout: float = 30.0) -> None:
        if not token:
            # Failing here rather than at the first request: an empty token is a
            # configuration mistake, and a 401 three calls later is a worse way
            # to find out about it.
            raise ValueError("a bearer token is required; `entire brain mcp --http` prints one")
        self.base_url = base_url.rstrip("/")
        self.token = token
        self.timeout = timeout

    def _get(self, path: str, **params: Any) -> dict[str, Any]:
        query = {k: v for k, v in params.items() if v is not None}
        url = f"{self.base_url}{path}"
        if query:
            url += "?" + urllib.parse.urlencode(query)
        request = urllib.request.Request(url, headers={"Authorization": f"Bearer {self.token}"})
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                return json.loads(response.read().decode("utf-8"))
        except urllib.error.HTTPError as error:
            body = error.read().decode("utf-8", "replace")
            try:
                parsed = json.loads(body)
                raise BrainError(error.code, parsed.get("error", body), parsed.get("hint", "")) from None
            except json.JSONDecodeError:
                raise BrainError(error.code, body.strip() or error.reason) from None
        except urllib.error.URLError as error:
            raise BrainError(0, f"could not reach {self.base_url}: {error.reason}") from None

    def status(self, branch: str | None = None) -> dict[str, Any]:
        """Fact counts for a branch: active, superseded, retracted, total."""
        return self._get("/v1/status", branch=branch)

    def facts(
        self, limit: int = 20, branch: str | None = None, include_all: bool = False
    ) -> list[dict[str, Any]]:
        """Durable facts, most useful first.

        Superseded and retracted facts are excluded unless include_all is set:
        a caller that renders these somewhere should not be shown things the
        brain no longer believes.
        """
        payload = self._get(
            "/v1/facts", limit=limit, branch=branch, all="true" if include_all else None
        )
        return payload.get("facts", [])

    def search(
        self, query: str, limit: int = 20, source: str | None = None, branch: str | None = None
    ) -> list[dict[str, Any]]:
        """Hybrid retrieval across facts, history and docs.

        source narrows the corpus ("fact", "history", "doc"); omitting it
        searches the default set.
        """
        if not query.strip():
            raise ValueError("query must not be empty")
        payload = self._get("/v1/search", q=query, limit=limit, source=source, branch=branch)
        return payload.get("results", [])

    def endpoints(self) -> Iterable[dict[str, str]]:
        """What this server exposes. Useful when a client is newer than a brain."""
        return self._get("/v1/").get("endpoints", [])

package cli

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"strings"
)

// A REST surface over the same listener as MCP.
//
// MCP is the right protocol for an agent and the wrong one for everything else.
// Putting a brain's knowledge into a dashboard, a CI check, a Slack bot or a
// notebook meant either speaking JSON-RPC by hand or shelling out to the CLI and
// parsing its output. Pieces is local-first and still serves a localhost HTTP
// API with Python and TypeScript clients, which is the proof that "we run
// locally" never explained why we shipped no HTTP surface at all.
//
// This adds plain resource endpoints beside the MCP one, on the same listener,
// under the same rules: absent unless --http is passed, loopback unless told
// otherwise, and the same bearer token. Sharing the listener is deliberate —
// two ports with two auth configurations is two chances to get it wrong.
//
// The endpoints are read-mostly and deliberately small. This is a way to get
// facts out of a brain, not a second API surface that has to keep pace with
// every CLI command.

const restAPIPrefix = "/v1/"

type restError struct {
	Error string `json:"error"`
	Hint  string `json:"hint,omitempty"`
}

func writeRESTError(w http.ResponseWriter, status int, message, hint string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(restError{Error: message, Hint: hint})
}

func writeRESTJSON(w http.ResponseWriter, value any) {
	w.Header().Set("Content-Type", "application/json")
	encoder := json.NewEncoder(w)
	encoder.SetIndent("", "  ")
	_ = encoder.Encode(value)
}

// restLimit reads a bounded limit. An unbounded limit on an endpoint that
// serialises records is a way to turn one request into all of memory, so the
// ceiling is enforced here rather than trusted from the caller.
func restLimit(r *http.Request, fallback, max int) (int, error) {
	raw := strings.TrimSpace(r.URL.Query().Get("limit"))
	if raw == "" {
		return fallback, nil
	}
	value, err := strconv.Atoi(raw)
	if err != nil {
		return 0, fmt.Errorf("limit must be an integer")
	}
	if value < 1 {
		return 0, fmt.Errorf("limit must be at least 1")
	}
	if value > max {
		return 0, fmt.Errorf("limit must be at most %d", max)
	}
	return value, nil
}

const (
	restDefaultLimit = 20
	restMaxLimit     = 200
)

// registerRESTRoutes adds the resource endpoints to an existing mux. The caller
// has already applied authentication, so nothing here re-implements it — one
// auth path for both surfaces is the point of sharing a listener.
func registerRESTRoutes(mux *http.ServeMux, opts Options) {
	mux.HandleFunc(restAPIPrefix, func(w http.ResponseWriter, r *http.Request) {
		resource := strings.Trim(strings.TrimPrefix(r.URL.Path, restAPIPrefix), "/")
		switch {
		case resource == "status" && r.Method == http.MethodGet:
			restStatus(w, r, opts)
		case resource == "facts" && r.Method == http.MethodGet:
			restFacts(w, r, opts)
		case resource == "search" && r.Method == http.MethodGet:
			restSearch(w, r, opts)
		case resource == "":
			// A bare /v1/ lists what exists. An API you can discover from the
			// root is one fewer document to keep in sync.
			writeRESTJSON(w, map[string]any{
				"endpoints": []map[string]string{
					{"method": "GET", "path": "/v1/status", "description": "brain freshness and source counts"},
					{"method": "GET", "path": "/v1/facts", "description": "durable facts; ?limit= and ?branch="},
					{"method": "GET", "path": "/v1/search", "description": "hybrid retrieval; ?q= required, ?limit=, ?source="},
					{"method": "POST", "path": "/", "description": "MCP JSON-RPC (the same tools the CLI exposes)"},
				},
				"auth": "Bearer token, the same one the MCP endpoint uses",
			})
		default:
			writeRESTError(w, http.StatusNotFound,
				fmt.Sprintf("no endpoint %s %s", r.Method, r.URL.Path),
				"GET /v1/ lists the endpoints that exist")
		}
	})
}

func restResolveTarget(r *http.Request, opts Options) (brainDir, branch string, err error) {
	requested := strings.TrimSpace(r.URL.Query().Get("branch"))
	_, brainDir, branch, err = resolveFactsTarget(r.Context(), opts, agentSurfaceTarget(opts, nil), requested)
	return brainDir, branch, err
}

func restStatus(w http.ResponseWriter, r *http.Request, opts Options) {
	brainDir, branch, err := restResolveTarget(r, opts)
	if err != nil {
		writeRESTError(w, http.StatusBadRequest, err.Error(), "")
		return
	}
	facts, err := loadFacts(brainDir, branch)
	if err != nil {
		writeRESTError(w, http.StatusInternalServerError, err.Error(), "")
		return
	}
	active, superseded, retracted := 0, 0, 0
	for _, fact := range facts {
		switch fact.Status {
		case "", factStatusActive:
			active++
		case "superseded":
			superseded++
		default:
			retracted++
		}
	}
	writeRESTJSON(w, map[string]any{
		"branch": branch,
		"facts": map[string]int{
			"active": active, "superseded": superseded, "retracted": retracted, "total": len(facts),
		},
	})
}

func restFacts(w http.ResponseWriter, r *http.Request, opts Options) {
	limit, err := restLimit(r, restDefaultLimit, restMaxLimit)
	if err != nil {
		writeRESTError(w, http.StatusBadRequest, err.Error(), fmt.Sprintf("limit is 1..%d", restMaxLimit))
		return
	}
	brainDir, branch, err := restResolveTarget(r, opts)
	if err != nil {
		writeRESTError(w, http.StatusBadRequest, err.Error(), "")
		return
	}
	facts, err := loadFacts(brainDir, branch)
	if err != nil {
		writeRESTError(w, http.StatusInternalServerError, err.Error(), "")
		return
	}
	// Retracted and superseded facts are excluded unless asked for. An API that
	// returned them by default would hand a dashboard things the brain no
	// longer believes.
	includeAll := strings.EqualFold(strings.TrimSpace(r.URL.Query().Get("all")), "true")
	out := make([]map[string]any, 0, limit)
	for _, fact := range facts {
		if !includeAll && fact.Status != "" && fact.Status != factStatusActive {
			continue
		}
		if len(out) == limit {
			break
		}
		out = append(out, map[string]any{
			"id": fact.ID, "text": fact.Text, "kind": fact.Kind, "paths": fact.Paths,
			"status": fact.Status, "origin": fact.Origin,
			"created_at": fact.CreatedAt, "updated_at": fact.UpdatedAt,
		})
	}
	writeRESTJSON(w, map[string]any{"branch": branch, "count": len(out), "limit": limit, "facts": out})
}

func restSearch(w http.ResponseWriter, r *http.Request, opts Options) {
	query := strings.TrimSpace(r.URL.Query().Get("q"))
	if query == "" {
		writeRESTError(w, http.StatusBadRequest, "q is required", "GET /v1/search?q=retry+policy")
		return
	}
	limit, err := restLimit(r, restDefaultLimit, restMaxLimit)
	if err != nil {
		writeRESTError(w, http.StatusBadRequest, err.Error(), fmt.Sprintf("limit is 1..%d", restMaxLimit))
		return
	}
	brainDir, branch, err := restResolveTarget(r, opts)
	if err != nil {
		writeRESTError(w, http.StatusBadRequest, err.Error(), "")
		return
	}
	repoDir := opts.Env.RepoRoot
	results, err := retrieveUnifiedWithOptions(repoDir, brainDir, branch, query, limit, modeHybrid,
		retrievalOptions{Source: strings.TrimSpace(r.URL.Query().Get("source"))})
	if err != nil {
		writeRESTError(w, http.StatusInternalServerError, err.Error(), "")
		return
	}
	writeRESTJSON(w, map[string]any{"branch": branch, "query": query, "count": len(results), "results": results})
}

