	hist := map[int]int{}
	for _, page := range pages[:min(len(pages), 4)] {
		content := pdfPageContent(objects, page)
		p := &pdfParser{data: content}
		var operands []pdfValue
		for p.pos < len(p.data) {
			p.skipSpace()
			if p.pos >= len(p.data) {
				break
			}
			if op, ok := p.parseOperator(); ok {
				if op == "TJ" && len(operands) >= 1 {
					if items, ok := operands[len(operands)-1].([]pdfValue); ok {
						for _, it := range items {
							if f, ok := it.(float64); ok {
								hist[int(f/50)*50]++
							}
						}
					}
				}
				operands = operands[:0]
				continue
			}
			before := p.pos
			operands = append(operands, p.parseValue())
			if p.pos == before {
				p.pos++
			}
			p.stuck = false
		}
	}
	keys := []int{}
	for k := range hist {
		keys = append(keys, k)
	}
	sort.Ints(keys)
	fmt.Printf("  pages=%d TJ-number buckets (bucket:count):\n   ", len(pages))
	for _, k := range keys {
