// the order they were surfaced, so JSON output is stable across runs.
func sortedGlobalFactIDs(matches []factRecord, globalIDs map[string]bool) []string {
	var ids []string
	for _, f := range matches {
		if globalIDs[f.ID] {
			ids = append(ids, f.ID)
		}
	}
