		Warnings:        len(src.Warnings),
		PartialFailures: len(src.PartialFailures),
		WallMS:          roundMillis(wall),
		MaxRSSBytes:     processMaxRSSBytes(),
		HeapAllocBytes:  after.HeapAlloc,
		TempRoot:        tempRoot,
		Kept:            benchOpts.keep,
	}
	if !benchOpts.json {
