	var releasedBeforeDelivery bool
	_, err := deliverMCPResponse(context.Background(), opts, msg, func(response mcpMessage) error {
		// The state must exist and still be unreleased at delivery time.
		seenDuringDelivery = deliveredPrivacyState
		releasedBeforeDelivery = deliveredPrivacyReleased
		return nil
	})
