	// unaffected rather than silently capped at zero.
	var none *pdfDecodeBudget
	if !none.spend(1 << 30) {
		t.Fatal("a nil budget refused a spend")
	}
	if none.exhausted() {
		t.Fatal("a nil budget reported exhaustion")
	}
}

func TestPDFStopsReadingPagesOnceTheBudgetIsGone(t *testing.T) {
	// Many pages, each with a content stream that decodes to a lot of bytes and
	// almost no text — the shape that defeats an output-size check.
	const pages = 400
	filler := "q " + strings.Repeat("1 0 0 1 0 0 cm ", 40000) + "Q"
	b := &pdfBuilder{}
	b.add("<< /Type /Catalog /Pages 2 0 R >>")
	kids := make([]string, 0, pages)
	for i := 0; i < pages; i++ {
		kids = append(kids, fmt.Sprintf("%d 0 R", 3+i*2))
	}
	b.add(fmt.Sprintf("<< /Type /Pages /Kids [%s] /Count %d >>", strings.Join(kids, " "), pages))
	for i := 0; i < pages; i++ {
		b.add(fmt.Sprintf("<< /Type /Page /Parent 2 0 R /Resources << >> /Contents %d 0 R >>", 4+i*2))
		b.addStream(t, "", filler)
	}
	data := b.build()

	done := make(chan struct{})
	go func() {
		defer close(done)
		// The point is that it terminates having done bounded work, not what it
		// returns: a document of drawing operators has no text either way.
		_, _ = extractDocumentText("bomb.pdf", data)
	}()
	select {
	case <-done:
	case <-time.After(60 * time.Second):
		t.Fatal("extraction did not terminate; decompression is not bounded across the document")
