	case readErr := <-done:
		if readErr == nil {
			t.Fatalf("stdin past the %d-byte limit was read in full", int64(maxManifestBytes))
		}
	case <-time.After(30 * time.Second):
		t.Fatal("reading oversized stdin did not terminate")
	}
}
