package cli

import (
	"net"
	"net/http"
	"sync/atomic"
	"testing"
)

type countingListener struct {
	net.Listener
	closes atomic.Int32
}

func (l *countingListener) Close() error {
	l.closes.Add(1)
	return l.Listener.Close()
}

func TestProbeServeClosesTheListenerOnError(t *testing.T) {
	base, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	counting := &countingListener{Listener: base}
	server := &http.Server{Handler: http.NotFoundHandler()}

	// Make Accept fail permanently so Serve returns a non-ErrServerClosed error,
	// which is exactly the branch the finding says leaks.
	if err := base.Close(); err != nil {
		t.Fatal(err)
	}
	serveErr := server.Serve(counting)
	t.Logf("Serve returned %v; Close called on the listener %d time(s)", serveErr, counting.closes.Load())
	if serveErr == nil || serveErr == http.ErrServerClosed {
		t.Fatalf("this probe needs the error branch, got %v", serveErr)
	}
	if counting.closes.Load() == 0 {
		t.Fatal("Serve returned an error without closing the listener")
	}
}
EOF
