func TestProbeCountFileLinesRefusesNonRegularPaths(t *testing.T) {
	dir := t.TempDir()
	outside := filepath.Join(dir, "outside.txt")
	if err := os.WriteFile(outside, []byte("secret\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	repo := filepath.Join(dir, "repo")
	if err := os.MkdirAll(repo, 0o700); err != nil {
		t.Fatal(err)
	}
	link := filepath.Join(repo, "link.txt")
	if err := os.Symlink(outside, link); err != nil {
		t.Skipf("symlinks unavailable: %v", err)
	}
	if _, _, err := countFileLines(link); err == nil {
		t.Fatal("a tracked symlink pointing outside the repository was counted")
	} else {
		t.Logf("symlink out of the repo -> %v", err)
	}
	// And the regular file it points at is still readable when named directly,
	// so the refusal is about the path's kind, not about reads failing.
	if _, _, err := countFileLines(outside); err != nil {
		t.Fatalf("a regular file was unreadable: %v", err)
	}
	t.Log("countFileLines refuses anything os.Lstat says is not a regular file")
}
EOF
