func partialGapNamedInYesList(rows [][]string, sentence string) string {
	lower := strings.ToLower(sentence)
	for _, row := range rows {
		if !strings.Contains(row[9], "Was REAL GAP") {
			continue
		}
		if row[2] != "Partial" && row[3] != "Partial" {
