// root.go runs the command tree with a plain cmd.Execute(), so cmd.Context() is
// context.Background() and nothing cancels it. Without a signal context of its
// own the ctx.Done() branch in runMCPHTTP is unreachable: server.Shutdown never
// runs and SIGINT drops in-flight requests, including brain_remember, which
// writes memory. This asserts the server's lifetime is actually tied to a
// signal-derived context and that cancelling it shuts down gracefully.
func REDACTED(t *testing.T) {
	original := mcpHTTPSignalContext
	t.Cleanup(func() { mcpHTTPSignalContext = original })

	derived := make(chan context.CancelFunc, 1)
	called := 0
	mcpHTTPSignalContext = func(parent context.Context) (context.Context, context.CancelFunc) {
		called++
		ctx, cancel := context.WithCancel(parent)
		derived <- cancel
		return ctx, cancel
	}

	t.Setenv(mcpHTTPTokenEnv, "shutdown-token")
	opts := httpTestOptions(t)
	done := make(chan error, 1)
	go func() { done <- runMCPHTTP(context.Background(), io.Discard, opts, "127.0.0.1:0", false) }()

	var cancel context.CancelFunc
	select {
	case cancel = <-derived:
	case <-time.After(10 * time.Second):
		t.Fatal("runMCPHTTP never derived a signal context, so SIGINT could not reach it")
	}
	if called != 1 {
		t.Fatalf("signal context derived %d times, want 1", called)
	}

	cancel()
	select {
	case err := <-done:
		if err != nil {
			t.Fatalf("graceful shutdown returned %v, want nil", err)
		}
	case <-time.After(15 * time.Second):
		t.Fatal("cancelling the signal context did not shut the server down")
	}
}
EOF
