func loadGlobalFacts(env EntireEnv) ([]factRecord, error) {
	brainDir, err := globalBrainDir(env)
	if err != nil {
		return nil, err
	}
	if _, statErr := os.Stat(brainDir); statErr != nil {
		if os.IsNotExist(statErr) {
