// The per-package allowance is drawn down per part. Deducting it only on a part
// that yielded text meant a package whose parts each decompress to the cap and
// contain none never spent it -- so an archive of up to maxExtractZipEntries
// such parts could force that many near-full decompressions, which is exactly
// the aggregate this budget exists to bound.
func TestOfficeBudgetIsSpentByTextlessParts(t *testing.T) {
	// Highly compressible, well-formed, and carrying no <w:t> at all.
	filler := "<w:document><w:body>" + strings.Repeat("<w:p><w:r></w:r></w:p>", 40000) + "</w:body></w:document>"
	parts := map[string]string{
		"word/document.xml": "<w:document><w:body><w:p><w:r><w:t>The retry budget is thirty seconds.</w:t></w:r></w:p></w:body></w:document>",
	}
	for i := 0; i < 12; i++ {
		parts[fmt.Sprintf("word/footnotes%02d.xml", i)] = filler
	}

	start := time.Now()
	text, err := extractDocumentText("big.docx", zipFile(t, parts))
	elapsed := time.Since(start)
	if err != nil {
		t.Fatalf("extract: %v", err)
	}
	t.Logf("elapsed %s, %d chars", elapsed, len(text))

	// The textless parts must have consumed the allowance, so the walk stops
	// rather than decompressing every one of them at full size.
	if elapsed > 20*time.Second {
		t.Fatalf("textless parts did not spend the budget: %s", elapsed)
	}
}
EOF
