cat > internal/cli/zz_fts_probe_test.go <<'EOF'
package cli

import (
	"database/sql"
	"fmt"
	"path/filepath"
	"testing"
	"time"
)

func TestProbeFTS5VsScan(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "probe.sqlite")
	db, err := sql.Open(sqliteDriverName, path)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()

	if _, err := db.Exec(`CREATE TABLE plain (id TEXT PRIMARY KEY, text TEXT NOT NULL)`); err != nil {
		t.Fatal(err)
	}
	if _, err := db.Exec(`CREATE VIRTUAL TABLE fts USING fts5(id, text)`); err != nil {
		t.Skipf("FTS5 unavailable in this build: %v", err)
	}

	const n = 200000
	tx, _ := db.Begin()
	for i := 0; i < n; i++ {
		body := fmt.Sprintf("func handler%d processes requests and returns a response payload alpha beta gamma", i)
		if i == n-1 {
			body += " UNIQUESENTINELTOKEN"
		}
		id := fmt.Sprintf("sym:%d", i)
		tx.Exec(`INSERT INTO plain(id,text) VALUES(?,?)`, id, body)
		tx.Exec(`INSERT INTO fts(id,text) VALUES(?,?)`, id, body)
	}
	if err := tx.Commit(); err != nil {
		t.Fatal(err)
	}
	t.Logf("rows: %d", n)

	var got string
	start := time.Now()
	err = db.QueryRow(`SELECT id FROM plain WHERE instr(lower(text), ?) > 0 LIMIT 1`, "uniquesentineltoken").Scan(&got)
	scanTime := time.Since(start)
	if err != nil {
		t.Fatalf("scan query: %v", err)
	}

	start = time.Now()
	err = db.QueryRow(`SELECT id FROM fts WHERE text MATCH ? LIMIT 1`, "UNIQUESENTINELTOKEN").Scan(&got)
	ftsTime := time.Since(start)
	if err != nil {
		t.Fatalf("fts query: %v", err)
	}

	t.Logf("instr scan: %v", scanTime)
	t.Logf("FTS5 MATCH: %v", ftsTime)
	t.Logf("speedup: %.1fx", float64(scanTime)/float64(max(ftsTime, 1)))
}
EOF
go test ./internal/cli/ -run '^TestProbeFTS5VsScan$' -count=1 -v 2>&1 | grep -E "rows:|instr scan|FTS5 MATCH|speedup|SKIP|FAIL" | head -6

