package cli

import (
	"database/sql"
	"fmt"
	"path/filepath"
	"sort"
	"testing"
	"time"
)

func TestProbeTrigramEquivalenceAndSpeed(t *testing.T) {
	dir := t.TempDir()
	db, err := sql.Open(sqliteDriverName, filepath.Join(dir, "p.sqlite"))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.Exec(`CREATE TABLE plain (id TEXT PRIMARY KEY, text TEXT NOT NULL)`); err != nil {
		t.Fatal(err)
	}
	if _, err := db.Exec(`CREATE VIRTUAL TABLE tri USING fts5(id UNINDEXED, text, tokenize='trigram')`); err != nil {
		t.Skipf("trigram tokenizer unavailable: %v", err)
	}
	const n = 150000
	tx, _ := db.Begin()
	for i := 0; i < n; i++ {
		body := fmt.Sprintf("func HandleRequest%d(ctx context.Context) error // retry.policy budget alpha", i)
		if i%1000 == 0 {
			body += " ServeHTTP"
		}
		id := fmt.Sprintf("sym:%d", i)
		tx.Exec(`INSERT INTO plain(id,text) VALUES(?,?)`, id, body)
		tx.Exec(`INSERT INTO tri(id,text) VALUES(?,?)`, id, body)
	}
	if err := tx.Commit(); err != nil {
		t.Fatal(err)
	}

	collect := func(q string, useFTS bool) ([]string, time.Duration) {
		var rows *sql.Rows
		var err error
		start := time.Now()
		if useFTS {
			rows, err = db.Query(`SELECT id FROM tri WHERE text LIKE '%' || ? || '%'`, q)
		} else {
			rows, err = db.Query(`SELECT id FROM plain WHERE instr(lower(text), lower(?)) > 0`, q)
		}
		if err != nil {
			t.Fatalf("query %q fts=%v: %v", q, useFTS, err)
		}
		defer rows.Close()
		var out []string
		for rows.Next() {
			var id string
			rows.Scan(&id)
			out = append(out, id)
		}
		sort.Strings(out)
		return out, time.Since(start)
	}

	// Substring queries, including one that is NOT a token boundary.
	for _, q := range []string{"ServeHTTP", "andleRequest7", "retry.policy", "HTTP"} {
		want, scanT := collect(q, false)
		got, ftsT := collect(q, true)
		same := len(want) == len(got)
		if same {
			for i := range want {
				if want[i] != got[i] {
					same = false
					break
				}
			}
		}
		t.Logf("%-14s matches=%-6d identical=%-5v  scan=%-10v trigram=%-10v speedup=%.1fx",
			q, len(want), same, scanT, ftsT, float64(scanT)/float64(max(ftsT, 1)))
		if !same {
			t.Errorf("query %q: trigram returned %d rows, instr returned %d", q, len(got), len(want))
		}
	}
}
EOF
go test ./internal/cli/ -run '^TestProbeTrigramEquivalenceAndSpeed$' -count=1 -v 2>&1 | grep -E "matches=|SKIP|FAIL|unavailable" | head -8

