p='internal/cli/semantic.go'
s=open(p).read()

# 1. schema: real trigram FTS5 index
old='`CREATE TABLE symbol_fts (id TEXT PRIMARY KEY, text TEXT NOT NULL)`,'
new='''// A trigram FTS5 index rather than a plain table. Every search here is a
		// substring match, and against an ordinary table that is instr() over
		// every row -- an O(corpus) scan on a table whose name promised an
		// index. The trigram tokenizer keeps substring semantics exactly
		// (matches need not fall on a token boundary) while making the lookup
		// indexed, which is what stops query latency growing with the codebase.
		`CREATE VIRTUAL TABLE symbol_fts USING fts5(id UNINDEXED, text, tokenize='trigram')`,'''
assert old in s
s=s.replace(old,new,1)

# 2. insert: FTS5 virtual tables have no PRIMARY KEY, so OR REPLACE cannot dedupe
