package cli

import (
	"database/sql"
	"fmt"
	"path/filepath"
	"testing"
	"time"
)

// Times the three scan sites against the two schemas on the same data.
func TestProbeScalingBeforeAfter(t *testing.T) {
	for _, n := range []int{50000, 200000} {
		dir := t.TempDir()
		db, err := sql.Open(sqliteDriverName, filepath.Join(dir, "s.sqlite"))
		if err != nil {
			t.Fatal(err)
		}
		if _, err := db.Exec(`CREATE TABLE plain (id TEXT PRIMARY KEY, text TEXT NOT NULL)`); err != nil {
			t.Fatal(err)
		}
		if _, err := db.Exec(`CREATE VIRTUAL TABLE tri USING fts5(id UNINDEXED, text, tokenize='trigram')`); err != nil {
			t.Skip("no trigram")
		}
		tx, _ := db.Begin()
		for i := 0; i < n; i++ {
			body := fmt.Sprintf("func Handler%d(ctx context.Context) error internal/svc/file%d.go Go function", i, i%997)
			if i%5000 == 0 {
				body += " invalidateCache"
			}
			id := fmt.Sprintf("sym:%d", i)
			tx.Exec(`INSERT INTO plain(id,text) VALUES(?,?)`, id, body)
			tx.Exec(`INSERT INTO tri(id,text) VALUES(?,?)`, id, body)
		}
		tx.Commit()

		// A realistic phrase: verbatim miss, then one DF lookup per token.
		tokens := []string{"invalidateCache", "context", "handler"}
		phrase := "how is the cache invalidated"

		timeIt := func(fts bool) time.Duration {
			start := time.Now()
			var c int
			if fts {
				db.QueryRow(`SELECT count(*) FROM tri WHERE text LIKE '%'||?||'%' ESCAPE '\'`, phrase).Scan(&c)
				for _, tok := range tokens {
					db.QueryRow(`SELECT count(*) FROM tri WHERE text LIKE '%'||?||'%' ESCAPE '\'`, tok).Scan(&c)
				}
			} else {
				db.QueryRow(`SELECT count(*) FROM plain WHERE instr(lower(text), ?) > 0`, phrase).Scan(&c)
				for _, tok := range tokens {
					db.QueryRow(`SELECT count(*) FROM plain WHERE instr(lower(text), ?) > 0`, tok).Scan(&c)
				}
			}
			return time.Since(start)
		}
		before, after := timeIt(false), timeIt(true)
		t.Logf("n=%-7d scan=%-12v trigram=%-12v speedup=%.1fx", n, before, after, float64(before)/float64(max(after, 1)))
		db.Close()
	}
}
EOF
