package cli

import (
	"database/sql"
	"path/filepath"
	"testing"
)

// Document frequency feeds IDF weighting, so the one-pass form has to return
// exactly what the per-token form returned. An approximation here would not
// fail loudly — it would quietly re-rank every multi-word search.
func TestTokenDocumentFrequenciesMatchPerTokenCounts(t *testing.T) {
	db := newTokenDFFixture(t)

	tokens := []string{"retries", "cache", "handler", "absent", "context"}
	got, err := tokenDocumentFrequencies(db, tokens)
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != len(tokens) {
		t.Fatalf("got %d counts for %d tokens", len(got), len(tokens))
	}
	for i, token := range tokens {
		var want int
		// The exact query this replaced.
		if err := db.QueryRow(
			`SELECT count(*) FROM symbol_fts WHERE instr(lower(text), ?) > 0`, token,
		).Scan(&want); err != nil {
			t.Fatal(err)
		}
		if got[i] != want {
			t.Fatalf("token %q: one-pass counted %d, per-token counted %d", token, got[i], want)
		}
	}
}

func TestTokenDocumentFrequenciesCountsAbsentTokensAsZero(t *testing.T) {
	db := newTokenDFFixture(t)
	got, err := tokenDocumentFrequencies(db, []string{"absent"})
	if err != nil {
		t.Fatal(err)
	}
	// Zero matters: the caller drops a token with df == 0 rather than giving it
	// an infinite IDF weight.
	if len(got) != 1 || got[0] != 0 {
		t.Fatalf("absent token counted %v, want [0]", got)
	}
}

func TestTokenDocumentFrequenciesHandlesNoTokens(t *testing.T) {
	db := newTokenDFFixture(t)
	got, err := tokenDocumentFrequencies(db, nil)
	if err != nil {
		t.Fatalf("empty token list errored: %v", err)
	}
	if len(got) != 0 {
		t.Fatalf("empty token list produced %v", got)
	}
}

func TestTokenDocumentFrequenciesPreservesTokenOrder(t *testing.T) {
	// The caller indexes the result by token position, so a reordering would
	// attach one token's weight to another.
	db := newTokenDFFixture(t)
	got, err := tokenDocumentFrequencies(db, []string{"absent", "retries"})
	if err != nil {
		t.Fatal(err)
	}
	if got[0] != 0 || got[1] == 0 {
		t.Fatalf("counts came back out of order: %v", got)
	}
}

func newTokenDFFixture(t *testing.T) *sql.DB {
	t.Helper()
	db, err := sql.Open(sqliteDriverName, filepath.Join(t.TempDir(), "df.sqlite"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { db.Close() })
	if _, err := db.Exec(`CREATE TABLE symbol_fts (id TEXT PRIMARY KEY, text TEXT NOT NULL)`); err != nil {
		t.Fatal(err)
	}
	rows := []struct{ id, text string }{
		{"s1", "func handleRetries(ctx context.Context) error"},
		{"s2", "func invalidateCache(ctx context.Context)"},
		{"s3", "type RetriesPolicy struct"},
		{"s4", "func Handler(w http.ResponseWriter)"},
		{"s5", "UPPERCASE RETRIES SHOUTED"},
	}
	for _, r := range rows {
		if _, err := db.Exec(`INSERT INTO symbol_fts(id, text) VALUES (?, ?)`, r.id, r.text); err != nil {
			t.Fatal(err)
		}
	}
	return db
}
EOF
