assert anchor in s
s = s.replace(anchor, helper.strip() + "\n\n" + anchor, 1)

s = s.replace(
  '''		snapshotHeader, snapshotCounts, snapshotErr := readSemanticSnapshotSummary(snapshotPath, storage.Key)''',
  '''		snapshotHeader, snapshotCounts, snapshotErr := verifiedSnapshotSummary(snapshotPath, storage.Key)''', 1)
s = s.replace(
  '''		} else if err := validateSemanticSQLiteStore(filepath.Join(storage.BrainDir, storePath), source.Symbols, source.Relations); err != nil {''',
  '''		} else if err := verifiedSQLiteStore(filepath.Join(storage.BrainDir, storePath), source.Symbols, source.Relations); err != nil {''', 1)

if '\n\t"sync"\n' not in s:
    s = s.replace('\n\t"strings"\n', '\n\t"strings"\n\t"sync"\n', 1)
open(p,'w').write(s)
print("patched")
