// A workbook declares its shared-string table, and the reader accumulated it
// without a ceiling. Cells that point past the table already render empty
// rather than wrong, so stopping is a safe degradation for a pathological file.
func TestSharedStringTableIsBounded(t *testing.T) {
	var sb strings.Builder
	sb.WriteString(`<sst>`)
