p='internal/cli/distill_cmd.go'; s=open(p).read()

# 1. lift the usage block out
usage_block = '''	usage := distillProviderUsage{Source: distillUsageSourceOllama}
	if parsed.PromptEvalCount != nil {
		usage.Reported = true
		usage.InputReported = true
		usage.InputTokens = *parsed.PromptEvalCount
	}
	if parsed.EvalCount != nil {
		usage.Reported = true
		usage.OutputReported = true
		usage.OutputTokens = *parsed.EvalCount
	}
	// Error responses may still consume model tokens; TotalAgentCalls also
	// counts failed attempts, so retain provider-reported usage before failing.
	recordDistillProviderUsage(ctx, usage)
'''
assert s.count(usage_block)==1, "usage block anchor"
s = s.replace(usage_block, '')

# 2. reinsert it immediately after the negative-count guard, before every failing return
neg = '''	if (parsed.PromptEvalCount != nil && *parsed.PromptEvalCount < 0) || (parsed.EvalCount != nil && *parsed.EvalCount < 0) {
		return "", errors.New("ollama returned negative token counts")
	}
'''
assert s.count(neg)==1, "negative guard anchor"
lifted = neg + '''	// Recorded before the checks below, not after. Every one of them fails a
	// call the model has already been paid for, and the truncation case is the
	// most expensive of all — it burns a full context window. Leaving the
	// record until after them dropped exactly the costliest calls from
	// accounting. TotalAgentCalls counts failed attempts too, so the usage has
	// to be retained to match.
''' + usage_block
s = s.replace(neg, lifted)

# 3. move the oversized-response check to after the usage record
over = '''	if len(parsed.Response) > distillMaxOutputBytes {
		return "", fmt.Errorf("ollama output exceeds %d bytes", distillMaxOutputBytes)
	}
'''
assert s.count(over)==1, "oversize anchor"
s = s.replace(over, '')
# reinsert right after the recordDistillProviderUsage call
rec = '	recordDistillProviderUsage(ctx, usage)\n'
assert s.count(rec)==1
s = s.replace(rec, rec + over)
open(p,'w').write(s); print("usage recording lifted above the failing returns")
