file: internal/agentsetup/migration.go
func Context(explicit, host string) (string, error) {
	p := explicit
	if p == "" {
		p = host
	}
	if p != "" {
		abs, err := filepath.Abs(p)
		if err != nil {
			return "", err
		}
		info, err := os.Stat(abs)
		if err != nil {
			return "", err
		}
		if !info.IsDir() {
			return "", fmt.Errorf("project root is not a directory: %s", abs)
		}
		return abs, nil
	}
	p, err := os.Getwd()
	if err != nil {
		return "", err
	}
	for {
		_, err := os.Lstat(filepath.Join(p, ".git"))
		if err == nil {
			return p, nil
		}
		if !os.IsNotExist(err) {
			return "", err
		}
		parent := filepath.Dir(p)
		if parent == p {
			return "", nil
		}
		p = parent
	}
}

