	report := &brainStatusReport{Facts: &brainFactsStatus{Facts: 0}}
	var out bytes.Buffer
	renderBrainStatusText(&out, report, "entire brain")

	if strings.Contains(out.String(), "verification:") {
		t.Fatalf("a brain with no facts must not advertise verification; got:\n%s", out.String())
	}
}
